 37	export function encodeSnapshot(state: GameState): string {
 38	  const named = state.name.length > 0;
 39	  return JSON.stringify(
 40	    {
 41	      version: named ? NAMED_SNAPSHOT_VERSION : SNAPSHOT_VERSION,
 42	      ...(named ? { name: state.name } : {}),
 43	      boardCode: state.boardCode,
 44	      matched: [...state.matched].sort((left, right) => left - right),
 45	      // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
 46	      // pending time up keeps a mismatch at 1ms or more.
 47	      selection:
 48	        state.selection.kind === SelectionKind.mismatch
 49	          ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
 50	          : state.selection,
 51	      moves: state.moves,
 52	      elapsedMs: Math.floor(state.elapsedMs),
 53	      started: state.started,
 54	    },
 55	    null,
 56	    2,
 57	  );
 58	}
