 60	export function decodeSnapshot(text: string): GameState | null {
 61	  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
 62	  if (!isJsonObject(value)) return null;
 63	  const keys =
 64	    value.version === SNAPSHOT_VERSION
 65	      ? SNAPSHOT_KEYS
 66	      : value.version === NAMED_SNAPSHOT_VERSION
 67	        ? NAMED_SNAPSHOT_KEYS
 68	        : null;
 69	  if (!keys || !hasExactKeys(value, keys)) return null;
 70	  let name = '';
 71	  if (value.version === NAMED_SNAPSHOT_VERSION) {
 72	    if (!isValidDealName(value.name) || value.name.length === 0) return null;
 73	    name = value.name;
 74	  }
 75	  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
 76	  if (
 77	    !isNonnegativeSafeInteger(value.moves) ||
 78	    value.moves > MOVES_MAX ||
 79	    !isNonnegativeSafeInteger(value.elapsedMs) ||
 80	    value.elapsedMs > ELAPSED_MAX_MS ||
 81	    typeof value.started !== 'boolean'
 82	  )
 83	    return null;
 84	  const initial = createGame(value.boardCode);
 85	  const matched = readMatched(value.matched, initial);
 86	  if (!matched) return null;
 87	  const selection = readSelection(value.selection, initial, matched);
 88	  if (!selection) return null;
 89	  const state: GameState = {
 90	    ...initial,
 91	    name,
 92	    matched,
 93	    selection,
 94	    moves: value.moves,
 95	    elapsedMs: value.elapsedMs,
 96	    started: value.started,
 97	  };
 98	  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
 99	  if (state.moves < minimumMoves) return null;
100	  if (
101	    !state.started &&
102	    (state.moves !== 0 ||
103	      state.elapsedMs !== 0 ||
104	      matched.length !== 0 ||
105	      selection.kind !== SelectionKind.closed)
106	  )
107	    return null;
108	  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
109	  return state;
110	}

